def add_categories():
    """Add colors to the database"""
    for average in averages:
        category_id = ProductCategories.objects.get(category_name=average["category_name"])
        CategoryAverages.objects.create(
            category=category_id,
            avg_days_to_10=average["avg_days_to_10"],
            avg_days_to_20=average["avg_days_to_20"],
            avg_days_to_30=average["avg_days_to_30"],
            avg_days_to_40=average["avg_days_to_40"],
            avg_days_to_50=average["avg_days_to_50"],
            avg_days_to_60=average["avg_days_to_60"],
            avg_days_to_70=average["avg_days_to_70"],
            avg_days_to_80=average["avg_days_to_80"],
            avg_days_to_90=average["avg_days_to_90"],
            avg_days_to_100=average["avg_days_to_100"]
        )
        print(f"{category_id} was created successfully")


if __name__ == "__main__":
    add_categories()
